import React, { useState, useEffect } from "react";
import { getNotes, createNote, updateNote, deleteNote } from "./api";
import "./App.css";

function App() {
  const [notes, setNotes] = useState([]);
  const [newNote, setNewNote] = useState("");
  const [editingNoteId, setEditingNoteId] = useState(null);
  const [editingNoteContent, setEditingNoteContent] = useState("");
  const [showArchived, setShowArchived] = useState(false);
  const [selectedTag, setSelectedTag] = useState("");
  const [tags, setTags] = useState([]); // Lista de etiquetas globales

  // Cargar notas al iniciar
  useEffect(() => {
    loadNotes();
  }, []);

  // Función para cargar las notas
  const loadNotes = async () => {
    const data = await getNotes();
    const formattedNotes = data.map(note => ({ ...note, tags: note.tags || [] }));
    setNotes(formattedNotes);

    // Obtener todas las etiquetas únicas
    const allTags = [...new Set(formattedNotes.flatMap(note => note.tags))];
    setTags(allTags);
  };

  // Agregar una nueva nota
  const handleAddNote = async () => {
    if (newNote.trim() === "") return;

    try {
      const newNoteData = {
        title: "Nueva nota",
        content: newNote,
        archived: false,
        tags: [], // Inicializar sin etiquetas
      };

      await createNote(newNoteData);
      setNewNote("");
      await loadNotes();
    } catch (error) {
      console.error("❌ Error al agregar la nota:", error);
    }
  };

  // Editar una nota
  const handleEditNote = async (id, newContent) => {
    try {
      await updateNote(id, { content: newContent });
      setEditingNoteId(null); // Salir del modo edición
      await loadNotes();
    } catch (error) {
      console.error("❌ Error al editar la nota:", error);
    }
  };

  // Eliminar una nota
  const handleDeleteNote = async (id) => {
    await deleteNote(id);
    await loadNotes();
  };

  // Archivar/Desarchivar una nota
  const handleArchiveNote = async (id, archived) => {
    await updateNote(id, { archived: !archived });
    await loadNotes();
  };

  // Agregar una etiqueta a una nota
  const handleAddTag = async (id, tag) => {
    if (!tag.trim()) return;
    const note = notes.find(n => n.id === id);
    if (!note.tags.includes(tag)) {
      const updatedTags = [...note.tags, tag];
      await updateNote(id, { tags: updatedTags });
      await loadNotes();
    }
  };

  // Eliminar una etiqueta de una nota
  const handleRemoveTag = async (id, tag) => {
    const note = notes.find(n => n.id === id);
    const updatedTags = note.tags.filter(t => t !== tag);
    await updateNote(id, { tags: updatedTags });
    await loadNotes();
  };

  // Filtrar notas activas o archivadas
  const filteredNotes = showArchived
    ? notes.filter(note => note.archived)
    : notes.filter(note => !note.archived);

  // Filtrar notas por etiqueta
  const notesToDisplay = selectedTag
    ? filteredNotes.filter(note => note.tags.includes(selectedTag))
    : filteredNotes;

  return (
    <div className="container">
      <h1>Notas</h1>

      {/* Agregar una nueva nota */}
      <input
        value={newNote}
        onChange={(e) => setNewNote(e.target.value)}
        placeholder="Escribe una nota"
      />
      <button onClick={handleAddNote}>Agregar Nota</button>

      {/* Botón para alternar entre notas activas y archivadas */}
      <button onClick={() => setShowArchived(!showArchived)}>
        {showArchived ? "Ver Notas Activas" : "Ver Notas Archivadas"}
      </button>

      {/* Filtrar por etiqueta */}
      <div className="select-container">
        <h3>Filtrar por etiqueta:</h3>
        <select onChange={(e) => setSelectedTag(e.target.value)} value={selectedTag}>
          <option value="">Todas</option>
          {tags.map(tag => (
            <option key={tag} value={tag}>{tag}</option>
          ))}
        </select>
      </div>

      {/* Lista de notas */}
      <h2>{showArchived ? "Notas Archivadas" : "Notas Activas"}</h2>
      <ul>
        {notesToDisplay.map((note) => (
          <li key={note.id}>
            {editingNoteId === note.id ? (
              // Modo edición
              <>
                <input
                  value={editingNoteContent}
                  onChange={(e) => setEditingNoteContent(e.target.value)}
                />
                <button onClick={() => handleEditNote(note.id, editingNoteContent)}>
                  Guardar
                </button>
                <button onClick={() => setEditingNoteId(null)}>Cancelar</button>
              </>
            ) : (
              // Modo visualización
              <>
                {note.content}
                <button onClick={() => handleArchiveNote(note.id, note.archived)}>
                  {note.archived ? "Desarchivar" : "Archivar"}
                </button>
                <button onClick={() => handleDeleteNote(note.id)}>🗑</button>
                <button
                  onClick={() => {
                    setEditingNoteId(note.id);
                    setEditingNoteContent(note.content);
                  }}
                >
                  Editar
                </button>

                {/* Etiquetas */}
                <div>
                  <strong>Etiquetas:</strong> {note.tags.join(", ")}
                  <input
                    type="text"
                    placeholder="Nueva etiqueta"
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        handleAddTag(note.id, e.target.value.trim());
                        e.target.value = "";
                      }
                    }}
                  />
                  {note.tags.map(tag => (
                    <button key={tag} onClick={() => handleRemoveTag(note.id, tag)}>❌ {tag}</button>
                  ))}
                </div>
              </>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
